tool_input.content:
const B = 'http://localhost:3000';
const email = `probe-${Date.now()}@example.test`, password = 'Passw0rd!x';
const j = async (r) => { const t = await r.text(); try { return JSON.parse(t); } catch { return t; } };
const p = (...a) => console.log(...a.map((x) => (typeof x === 'string' ? x : JSON.stringify(x).slice(0, 600))));
let r = await fetch(B + '/api/Users', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email, password, passwordRepeat: password, securityQuestion: { id: 1 }, securityAnswer: 'x' }) });
p('reg', String(r.status), await j(r));
r = await fetch(B + '/rest/user/login', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email, password }) });
const login = await j(r); p('login', login);
const H = { 'content-type': 'application/json', authorization: 'Bearer ' + login.authentication.token };
r = await fetch(B + '/api/Deliverys', { headers: H }); p('deliv', await j(r));
r = await fetch(B + '/rest/wallet/balance', { headers: H }); p('wallet', await j(r));
r = await fetch(B + '/rest/basket/' + login.authentication.bid, { headers: H }); p('basket', await j(r));
r = await fetch(B + '/api/Quantitys', { headers: H }); p('qty', await j(r));
